def esc(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')

def main():
    rows = []
    for block in RAW.strip().split("\n"):
        block = block.strip()
        if not block or block.startswith("#"):
            continue
        parts = block.split("|||")
        if len(parts) != 11:
            raise SystemExit("bad row %s parts=%d\n%s" % (parts[0][:40], len(parts), block))
        rows.append(parts)
    out = ["(function(){",
           " var d = window.HUB_I18N_DICT; if(!d||!d.phrases) return;",
           " function t(de,ru,uk,pl,es,pt,fr,it,tr,nl){return {de:de,ru:ru,uk:uk,pl:pl,es:es,pt:pt,fr:fr,it:it,tr:tr,nl:nl};}",
           " var extra = {"]
    for p in rows:
        en = p[0]
        langs = p[1:]
        args = ",".join('"%s"' % esc(x) for x in langs)
        out.append('"%s": t(%s),' % (esc(en), args))
    out.append(" };")
    out.append(" Object.keys(extra).forEach(function(k){ d.phrases[k] = extra[k]; });")
    out.append("})();")
    (ROOT / "js" / "i18n-seed.js").write_text("\n".join(out), encoding="utf-8")
    print("seed", len(rows))

if __name__ == "__main__":
    main()
